import Fastify, { type FastifyInstance, type FastifyReply, type FastifyRequest } from "fastify";
import type { AppConfig, RateLimitConfig } from "./config.js";
import { Store, type AccountRow } from "./database.js";
import { ApiError, validationError, type ValidationIssue } from "./errors.js";
import { prepareDummyHash } from "./crypto/password.js";
import { CHAIN_ID, NETWORK } from "./crypto/wallet.js";
import { SlidingWindowRateLimiter } from "./rate-limit.js";
import { AuthService, normalizeEmail } from "./services/auth-service.js";
import { WalletService } from "./services/wallet-service.js";

declare module "fastify" {
  interface FastifyRequest {
    authenticatedAccount?: AccountRow;
    loginAuditOutcome?: {
      result: "SUCCESS" | "FAILURE";
      reason?: string;
    };
    pendingPublicRateLimit?: {
      kind: "register" | "login";
      retryAfterSeconds: number;
    };
  }

  interface FastifyInstance {
    exchangeStore: Store;
    authService: AuthService;
    walletService: WalletService;
  }
}

const EMAIL_PATTERN = /^[^@\s]+@[^@\s.]+(\.[^@\s.]+)+$/;
const KNOWN_ROUTES: Readonly<Record<string, readonly string[]>> = {
  "/api/v1/auth/register": ["POST"],
  "/api/v1/auth/login": ["POST"],
  "/api/v1/deposit-address": ["GET"],
  "/health": ["GET"],
};

interface CredentialsBody {
  email: string;
  password: string;
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function validateCredentialsBody(value: unknown, exactFields: boolean): CredentialsBody {
  const issues: ValidationIssue[] = [];
  if (!isRecord(value)) {
    throw validationError([{ field: "body", message: "Debe ser un objeto JSON" }]);
  }
  if (!("email" in value)) issues.push({ field: "email", message: "Campo requerido" });
  else if (typeof value.email !== "string") issues.push({ field: "email", message: "Debe ser string" });
  if (!("password" in value)) issues.push({ field: "password", message: "Campo requerido" });
  else if (typeof value.password !== "string") {
    issues.push({ field: "password", message: "Debe ser string" });
  }
  if (exactFields) {
    for (const field of Object.keys(value)) {
      if (field !== "email" && field !== "password") {
        issues.push({ field, message: "Campo desconocido" });
      }
    }
  }
  if (issues.length > 0) throw validationError(issues);
  return value as unknown as CredentialsBody;
}

function validateRegistration(body: CredentialsBody): CredentialsBody {
  const email = normalizeEmail(body.email);
  if (email.length > 254 || !EMAIL_PATTERN.test(email)) {
    throw validationError([{ field: "email", message: "Formato de email inválido" }]);
  }
  const passwordLength = [...body.password].length;
  if (passwordLength < 8 || passwordLength > 128) {
    throw validationError([{ field: "password", message: "Debe tener entre 8 y 128 caracteres" }]);
  }
  return { email, password: body.password };
}

function bearerToken(request: FastifyRequest): string | undefined {
  const authorization = request.headers.authorization;
  if (typeof authorization !== "string") return undefined;
  const match = /^Bearer ([^\s]+)$/.exec(authorization);
  return match?.[1];
}

function sendRateLimit(reply: FastifyReply, retryAfterSeconds: number): never {
  reply.header("Retry-After", String(retryAfterSeconds));
  throw new ApiError("RATE_LIMITED", { retryAfterSeconds });
}

function isLoginRequest(request: FastifyRequest): boolean {
  return request.method === "POST" && request.url.split("?", 1)[0] === "/api/v1/auth/login";
}

function loginAttemptEmail(request: FastifyRequest): string {
  return isRecord(request.body) && typeof request.body.email === "string"
    ? request.body.email
    : "";
}

export async function buildApp(config: AppConfig): Promise<FastifyInstance> {
  const app = Fastify({
    logger: false,
    exposeHeadRoutes: false,
    routerOptions: { ignoreTrailingSlash: false },
  });
  const store = new Store(config);
  const walletService = new WalletService(store);
  const authService = new AuthService(store, walletService);
  const publicLimiter = new SlidingWindowRateLimiter();
  const protectedLimiter = new SlidingWindowRateLimiter();
  await prepareDummyHash();

  app.decorate("exchangeStore", store);
  app.decorate("walletService", walletService);
  app.decorate("authService", authService);

  app.addHook("onClose", async () => {
    store.close();
  });

  app.setErrorHandler((error, request, reply) => {
    if (request.pendingPublicRateLimit) {
      const retryAfterSeconds = request.pendingPublicRateLimit.retryAfterSeconds;
      const apiError = new ApiError("RATE_LIMITED", { retryAfterSeconds });
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
      }
      reply.header("Retry-After", String(retryAfterSeconds));
      reply.status(apiError.status).send(apiError.toBody());
      return;
    }
    if (error instanceof ApiError) {
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: error.code };
      }
      reply.status(error.status).send(error.toBody());
      return;
    }
    const fastifyError = error as Error & { code?: string; statusCode?: number };
    if (
      fastifyError.code === "FST_ERR_CTP_INVALID_MEDIA_TYPE" ||
      fastifyError.code === "FST_ERR_CTP_EMPTY_JSON_BODY" ||
      fastifyError.code === "FST_ERR_CTP_BODY_TOO_LARGE" ||
      fastifyError.statusCode === 400
    ) {
      const apiError = validationError([{ field: "body", message: "JSON inválido o Content-Type no soportado" }]);
      if (isLoginRequest(request)) {
        request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
      }
      reply.status(apiError.status).send(apiError.toBody());
      return;
    }
    const apiError = new ApiError("INTERNAL_ERROR");
    if (isLoginRequest(request)) {
      request.loginAuditOutcome = { result: "FAILURE", reason: apiError.code };
    }
    reply.status(apiError.status).send(apiError.toBody());
  });

  app.addHook("onResponse", async (request) => {
    if (!isLoginRequest(request)) return;
    const outcome = request.loginAuditOutcome ?? { result: "FAILURE", reason: "INTERNAL_ERROR" } as const;
    authService.auditLoginAttempt(
      loginAttemptEmail(request),
      outcome.result,
      outcome.reason,
      request.ip,
    );
  });

  app.setNotFoundHandler((request, reply) => {
    const path = request.url.split("?", 1)[0] ?? request.url;
    const allowed = KNOWN_ROUTES[path];
    const error = allowed && !allowed.includes(request.method)
      ? new ApiError("METHOD_NOT_ALLOWED", { method: request.method, allowed })
      : new ApiError("NOT_FOUND", { resource: "route", id: path });
    reply.status(error.status).send(error.toBody());
  });

  app.get("/health", async () => ({ status: "ok" }));

  const publicRateLimitCheck = (kind: "register" | "login", rateConfig: RateLimitConfig | undefined) =>
    async (request: FastifyRequest): Promise<void> => {
      if (!rateConfig) return;
      const result = publicLimiter.check(`${kind}:${request.ip}`, rateConfig);
      if (result.limited) {
        request.pendingPublicRateLimit = { kind, retryAfterSeconds: result.retryAfterSeconds };
      }
    };

  const enforcePublicRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const pending = request.pendingPublicRateLimit;
    if (!pending) return;
    sendRateLimit(reply, pending.retryAfterSeconds);
  };

  app.post(
    "/api/v1/auth/register",
    {
      onRequest: publicRateLimitCheck("register", config.registerRateLimit),
      preValidation: enforcePublicRateLimit,
    },
    async (request, reply) => {
      const schemaValid = validateCredentialsBody(request.body, true);
      const body = validateRegistration(schemaValid);
      if (store.findAccountByEmail(body.email)) {
        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: body.email });
      }
      const account = await authService.register(body.email, body.password);
      reply.status(201).send(account);
    },
  );

  app.post(
    "/api/v1/auth/login",
    {
      onRequest: publicRateLimitCheck("login", config.loginRateLimit),
      preValidation: enforcePublicRateLimit,
    },
    async (request, reply) => {
      const body = validateCredentialsBody(request.body, false);
      const result = await authService.login(body.email, body.password);
      request.loginAuditOutcome = { result: "SUCCESS" };
      reply.status(200).send(result);
    },
  );

  const authenticate = async (request: FastifyRequest): Promise<void> => {
    const token = bearerToken(request);
    const account = token ? authService.authenticate(token) : undefined;
    if (!account) throw new ApiError("UNAUTHENTICATED");
    request.authenticatedAccount = account;
  };

  const protectedRateLimit = async (request: FastifyRequest, reply: FastifyReply): Promise<void> => {
    const account = request.authenticatedAccount;
    if (!account) throw new ApiError("UNAUTHENTICATED");
    const result = protectedLimiter.check(
      `${account.account_id}:${request.routeOptions.url}`,
      { max: 60, windowSeconds: 60 },
    );
    if (result.limited) sendRateLimit(reply, result.retryAfterSeconds);
  };

  app.get(
    "/api/v1/deposit-address",
    { preHandler: [authenticate, protectedRateLimit] },
    async (request, reply) => {
      const query = isRecord(request.query) ? request.query : {};
      const asset = query.asset;
      if (typeof asset !== "string" || (asset !== "ETH" && asset !== "USDC")) {
        throw validationError([{ field: "asset", message: "Debe ser ETH o USDC" }]);
      }

      const chainId = query.chainId;
      const network = query.network;
      if (chainId !== undefined && String(chainId) !== CHAIN_ID) {
        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(chainId) });
      }
      if (network !== undefined && String(network).toLowerCase() !== NETWORK) {
        throw new ApiError("CHAIN_ID_MISMATCH", { expected: CHAIN_ID, got: String(network) });
      }

      const account = request.authenticatedAccount;
      if (!account) throw new ApiError("UNAUTHENTICATED");
      const assigned = walletService.getOrAssign(account.account_id);
      const response: Record<string, string> = {
        asset,
        address: assigned.address,
        network: NETWORK,
        chainId: CHAIN_ID,
      };
      if (asset === "USDC") response.tokenAddress = config.usdcMockAddress;
      reply.status(200).send(response);
    },
  );

  return app;
}
import { createHash, randomBytes, randomUUID } from "node:crypto";
import type { Store, AccountRow } from "../database.js";
import { ApiError } from "../errors.js";
import { hashPassword, verifyAgainstDummy, verifyPassword } from "../crypto/password.js";
import type { WalletService } from "./wallet-service.js";

export interface PublicAccount {
  accountId: string;
  email: string;
  status: "ACTIVE";
  createdAt: string;
}

export interface LoginResult {
  token: string;
  expiresAt: string;
}

function publicAccount(row: AccountRow): PublicAccount {
  return {
    accountId: row.account_id,
    email: row.email,
    status: row.status,
    createdAt: row.created_at,
  };
}

function tokenHash(token: string): string {
  return createHash("sha256").update(token, "utf8").digest("hex");
}

export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

export class AuthService {
  constructor(
    private readonly store: Store,
    private readonly walletService: WalletService,
  ) {}

  async register(email: string, password: string): Promise<PublicAccount> {
    const normalizedEmail = normalizeEmail(email);
    const passwordHash = await hashPassword(password);
    const account: AccountRow = {
      account_id: randomUUID(),
      email: normalizedEmail,
      password_hash: passwordHash,
      status: "ACTIVE",
      created_at: new Date().toISOString(),
    };
    try {
      this.store.transaction(() => {
        this.store.db.prepare(
          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
           VALUES (?, ?, ?, ?, ?)`,
        ).run(
          account.account_id,
          account.email,
          account.password_hash,
          account.status,
          account.created_at,
        );
        this.walletService.assignInsideTransaction(account.account_id);
      });
    } catch (error) {
      if (error instanceof Error && /UNIQUE constraint failed: accounts\.email/.test(error.message)) {
        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: normalizedEmail });
      }
      throw error;
    }
    return publicAccount(account);
  }

  async login(email: string, password: string): Promise<LoginResult> {
    const normalizedEmail = normalizeEmail(email);
    const account = this.store.findAccountByEmail(normalizedEmail);
    let valid = false;
    if (account) {
      valid = await verifyPassword(password, account.password_hash);
    } else {
      await verifyAgainstDummy(password);
    }

    if (!account || !valid) {
      throw new ApiError("INVALID_CREDENTIALS");
    }

    const token = randomBytes(32).toString("base64url");
    const now = new Date();
    const expiresAt = new Date(now.getTime() + this.store.config.sessionTtlSeconds * 1000).toISOString();
    this.store.db.prepare(
      "INSERT INTO sessions (token_hash, account_id, expires_at, created_at) VALUES (?, ?, ?, ?)",
    ).run(tokenHash(token), account.account_id, expiresAt, now.toISOString());
    return { token, expiresAt };
  }

  authenticate(token: string): AccountRow | undefined {
    const session = this.store.db.prepare(
      `SELECT a.account_id, a.email, a.password_hash, a.status, a.created_at, s.expires_at
       FROM sessions s JOIN accounts a ON a.account_id = s.account_id
       WHERE s.token_hash = ?`,
    ).get(tokenHash(token)) as (AccountRow & { expires_at: string }) | undefined;
    if (!session || Date.parse(session.expires_at) <= Date.now()) return undefined;
    return session;
  }

  auditLoginAttempt(
    email: string,
    result: "SUCCESS" | "FAILURE",
    reason?: string,
    origin?: string,
  ): void {
    const normalizedEmail = normalizeEmail(email);
    this.store.db.prepare(
      `INSERT INTO auth_audit (timestamp, email, result, reason, origin)
       VALUES (?, ?, ?, ?, ?)`,
    ).run(new Date().toISOString(), normalizedEmail, result, reason ?? null, origin ?? null);
  }
}
import { mkdirSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { DatabaseSync } from "node:sqlite";
import type { AppConfig } from "./config.js";
import {
  CHAIN_ID,
  NETWORK,
  decryptSeed,
  deriveAddress,
  encryptSeed,
  generateProjectSeed,
  mnemonicToSeed,
  validateProjectMnemonic,
} from "./crypto/wallet.js";

export interface AccountRow {
  account_id: string;
  email: string;
  password_hash: string;
  status: "ACTIVE";
  created_at: string;
}

export interface AddressRow {
  account_id: string;
  address_index: number;
  address: string;
  derivation_path: string;
  network: "sepolia";
  chain_id: "11155111";
  created_at: string;
}

export class Store {
  readonly db: DatabaseSync;
  readonly seed: Buffer;

  constructor(readonly config: AppConfig) {
    if (config.databasePath !== ":memory:") {
      mkdirSync(dirname(resolve(config.databasePath)), { recursive: true });
    }
    this.db = new DatabaseSync(config.databasePath);
    this.db.exec("PRAGMA foreign_keys = ON");
    this.db.exec("PRAGMA journal_mode = WAL");
    this.db.exec("PRAGMA synchronous = FULL");
    this.db.exec("PRAGMA busy_timeout = 5000");
    this.createSchema();
    this.seed = this.loadOrProvisionSeed();
    this.verifyWalletIntegrity();
  }

  close(): void {
    this.db.close();
  }

  transaction<T>(operation: () => T): T {
    this.db.exec("BEGIN IMMEDIATE");
    try {
      const result = operation();
      this.db.exec("COMMIT");
      return result;
    } catch (error) {
      this.db.exec("ROLLBACK");
      throw error;
    }
  }

  findAccountByEmail(email: string): AccountRow | undefined {
    return this.db.prepare(
      "SELECT account_id, email, password_hash, status, created_at FROM accounts WHERE email = ?",
    ).get(email) as AccountRow | undefined;
  }

  findAccountById(accountId: string): AccountRow | undefined {
    return this.db.prepare(
      "SELECT account_id, email, password_hash, status, created_at FROM accounts WHERE account_id = ?",
    ).get(accountId) as AccountRow | undefined;
  }

  findAddress(accountId: string): AddressRow | undefined {
    return this.db.prepare(
      `SELECT account_id, address_index, address, derivation_path, network, chain_id, created_at
       FROM deposit_addresses WHERE account_id = ?`,
    ).get(accountId) as AddressRow | undefined;
  }

  getAssignedAddresses(): AddressRow[] {
    return this.db.prepare(
      `SELECT account_id, address_index, address, derivation_path, network, chain_id, created_at
       FROM deposit_addresses ORDER BY address_index ASC`,
    ).all() as unknown as AddressRow[];
  }

  private createSchema(): void {
    this.db.exec(`
      CREATE TABLE IF NOT EXISTS accounts (
        account_id TEXT PRIMARY KEY,
        email TEXT NOT NULL UNIQUE,
        password_hash TEXT NOT NULL,
        status TEXT NOT NULL CHECK (status = 'ACTIVE'),
        created_at TEXT NOT NULL
      ) STRICT;

      CREATE TABLE IF NOT EXISTS sessions (
        token_hash TEXT PRIMARY KEY,
        account_id TEXT NOT NULL REFERENCES accounts(account_id),
        expires_at TEXT NOT NULL,
        created_at TEXT NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS sessions_account_id ON sessions(account_id);

      CREATE TABLE IF NOT EXISTS wallet_metadata (
        key TEXT PRIMARY KEY,
        value BLOB NOT NULL
      ) STRICT;

      CREATE TABLE IF NOT EXISTS deposit_addresses (
        account_id TEXT PRIMARY KEY REFERENCES accounts(account_id),
        address_index INTEGER NOT NULL UNIQUE CHECK (address_index >= 0 AND address_index < 2147483648),
        address TEXT NOT NULL UNIQUE,
        derivation_path TEXT NOT NULL,
        network TEXT NOT NULL CHECK (network = 'sepolia'),
        chain_id TEXT NOT NULL CHECK (chain_id = '11155111'),
        created_at TEXT NOT NULL
      ) STRICT;

      CREATE TABLE IF NOT EXISTS domain_events (
        event_id TEXT PRIMARY KEY,
        event_type TEXT NOT NULL CHECK (event_type = 'DepositAddressAssigned'),
        account_id TEXT NOT NULL REFERENCES accounts(account_id),
        payload TEXT NOT NULL,
        occurred_at TEXT NOT NULL
      ) STRICT;
      CREATE INDEX IF NOT EXISTS domain_events_account_id ON domain_events(account_id);

      CREATE TABLE IF NOT EXISTS skipped_address_indices (
        address_index INTEGER PRIMARY KEY CHECK (address_index >= 0 AND address_index < 2147483648),
        reason TEXT NOT NULL CHECK (reason = 'INVALID_BIP32_CHILD'),
        occurred_at TEXT NOT NULL
      ) STRICT;

      CREATE TABLE IF NOT EXISTS auth_audit (
        audit_id INTEGER PRIMARY KEY AUTOINCREMENT,
        timestamp TEXT NOT NULL,
        email TEXT NOT NULL,
        result TEXT NOT NULL CHECK (result IN ('SUCCESS', 'FAILURE')),
        reason TEXT,
        origin TEXT
      ) STRICT;
    `);
  }

  private loadOrProvisionSeed(): Buffer {
    const record = this.db.prepare("SELECT value FROM wallet_metadata WHERE key = 'encrypted_seed'").get() as
      | { value: Uint8Array }
      | undefined;
    if (record) {
      try {
        const seed = decryptSeed(Buffer.from(record.value), this.config.walletEncryptionKey);
        if (seed.length !== 64) throw new Error("Longitud de seed inválida");
        return seed;
      } catch {
        throw new Error("INTERNAL_ERROR: no se pudo descifrar o autenticar el seed custodial");
      }
    }

    const assignment = this.db.prepare("SELECT 1 AS present FROM deposit_addresses LIMIT 1").get();
    if (assignment) {
      throw new Error("INTERNAL_ERROR: hay asignaciones persistidas pero falta el seed custodial");
    }

    let seed: Buffer;
    if (this.config.hdMnemonic !== undefined) {
      const mnemonic = validateProjectMnemonic(this.config.hdMnemonic);
      seed = mnemonicToSeed(mnemonic, this.config.hdMnemonicPassphrase);
    } else {
      seed = generateProjectSeed(this.config.hdMnemonicPassphrase).seed;
    }
    const encrypted = encryptSeed(seed, this.config.walletEncryptionKey);
    this.transaction(() => {
      this.db.prepare("INSERT INTO wallet_metadata (key, value) VALUES ('encrypted_seed', ?)").run(encrypted);
      const persisted = this.db.prepare(
        "SELECT value FROM wallet_metadata WHERE key = 'encrypted_seed'",
      ).get() as { value: Uint8Array } | undefined;
      if (!persisted) throw new Error("No se pudo releer el seed cifrado");
      const verified = decryptSeed(Buffer.from(persisted.value), this.config.walletEncryptionKey);
      if (verified.length !== seed.length || !verified.equals(seed)) {
        throw new Error("No se pudo verificar el seed cifrado");
      }
    });
    return seed;
  }

  private verifyWalletIntegrity(): void {
    const row = this.db.prepare(
      "SELECT address_index, address FROM deposit_addresses ORDER BY address_index ASC LIMIT 1",
    ).get() as { address_index: number; address: string } | undefined;
    if (!row) return;
    try {
      const derived = deriveAddress(this.seed, row.address_index);
      if (derived.address !== row.address) throw new Error();
    } catch {
      throw new Error("INTERNAL_ERROR: falló el smoke test de integridad de la wallet HD");
    }
  }
}

export function addressRecord(
  accountId: string,
  addressIndex: number,
  address: string,
  derivationPath: string,
  createdAt: string,
): AddressRow {
  return {
    account_id: accountId,
    address_index: addressIndex,
    address,
    derivation_path: derivationPath,
    network: NETWORK,
    chain_id: CHAIN_ID,
    created_at: createdAt,
  };
}
import { buildApp } from "./app.js";
import { loadConfig } from "./config.js";
import { ApiError } from "./errors.js";

async function main(): Promise<void> {
  const config = loadConfig();
  const app = await buildApp(config);
  await app.listen({ host: config.host, port: config.port });
}

main().catch((error: unknown) => {
  const code = error instanceof ApiError && error.code === "VALIDATION_ERROR"
    ? "VALIDATION_ERROR"
    : "INTERNAL_ERROR";
  process.stderr.write(`${code}: el backend no pudo iniciar de forma segura\n`);
  process.exitCode = 1;
});
import { getAddress } from "ethers";

export interface AppConfig {
  host: string;
  port: number;
  databasePath: string;
  sessionTtlSeconds: number;
  walletEncryptionKey: Buffer;
  usdcMockAddress: string;
  sepoliaRpcUrl: string;
  hdMnemonic?: string;
  hdMnemonicPassphrase: string;
  registerRateLimit?: RateLimitConfig;
  loginRateLimit?: RateLimitConfig;
}

export interface RateLimitConfig {
  max: number;
  windowSeconds: number;
}

function positiveInt(name: string, raw: string | undefined, fallback?: number): number {
  if (raw === undefined && fallback !== undefined) return fallback;
  if (raw === undefined || !/^[1-9][0-9]*$/.test(raw)) {
    throw new Error(`INTERNAL_ERROR: ${name} debe ser un entero positivo`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new Error(`INTERNAL_ERROR: ${name} está fuera de rango`);
  }
  return value;
}

function encryptionKey(raw: string | undefined): Buffer {
  if (!raw) throw new Error("INTERNAL_ERROR: falta WALLET_ENCRYPTION_KEY");
  const value = raw.startsWith("base64:")
    ? Buffer.from(raw.slice(7), "base64")
    : Buffer.from(raw, "hex");
  if (value.length !== 32) {
    throw new Error("INTERNAL_ERROR: WALLET_ENCRYPTION_KEY debe contener exactamente 32 bytes");
  }
  return value;
}

function optionalRateLimit(
  env: NodeJS.ProcessEnv,
  maxName: string,
  windowName: string,
): RateLimitConfig | undefined {
  const max = env[maxName];
  const window = env[windowName];
  if (max === undefined && window === undefined) return undefined;
  if (max === undefined || window === undefined) {
    throw new Error(`INTERNAL_ERROR: ${maxName} y ${windowName} deben configurarse juntos`);
  }
  return { max: positiveInt(maxName, max), windowSeconds: positiveInt(windowName, window) };
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const ttl = positiveInt("SESSION_TTL_SECONDS", env.SESSION_TTL_SECONDS, 3600);
  if (ttl < 60 || ttl > 86_400) {
    throw new Error("INTERNAL_ERROR: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
  }

  if (!env.USDC_MOCK_ADDRESS) {
    throw new Error("INTERNAL_ERROR: falta USDC_MOCK_ADDRESS");
  }
  let usdcMockAddress: string;
  try {
    usdcMockAddress = getAddress(env.USDC_MOCK_ADDRESS);
  } catch {
    throw new Error("INTERNAL_ERROR: USDC_MOCK_ADDRESS no es una dirección Ethereum válida");
  }

  const sepoliaRpcUrl = env.SEPOLIA_RPC_URL;
