 44	async function requestJson<T>(path: string, init: RequestInit): Promise<T> {
 45	  let response: Response;
 46	  try {
 47	    response = await fetch(`${API_BASE_URL}${path}`, init);
 48	  } catch {
 49	    throw new NetworkError();
 50	  }
 51	
 52	  let body: unknown;
 53	  try {
 54	    body = await response.json();
 55	  } catch {
 56	    throw new NetworkError();
 57	  }
 58	
 59	  if (!response.ok) {
 60	    const envelope = body as ErrorEnvelope;
 61	    const code = envelope.error?.code;
 62	    if (typeof code === "string") {
 63	      throw new ApiResponseError(code, response.status, envelope.error?.details);
 64	    }
 65	    throw new NetworkError();
 66	  }
 67	  return body as T;
 68	}
