 72	    method: "POST",
 73	    headers: { "Content-Type": "application/json" },
 74	    body: JSON.stringify({ email, password }),
 75	  });
 76	  if (!isRecord(result) || typeof result.token !== "string" || result.token.length === 0
 77	    || typeof result.expiresAt !== "string" || !Number.isFinite(Date.parse(result.expiresAt))) {
 78	    throw new NetworkError();
 79	  }
 80	  return { token: result.token, expiresAt: result.expiresAt };
 81	}
