 10	let memorySession: Session | null = null;
 11	
 12	function isSession(value: unknown): value is Session {
 13	  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
 14	  const candidate = value as Record<string, unknown>;
 15	  return typeof candidate.token === "string" && candidate.token.length > 0
 16	    && typeof candidate.expiresAt === "string"
 17	    && Number.isFinite(Date.parse(candidate.expiresAt));
 18	}
