 20	export function persistSession(session: Session): void {
 21	  memorySession = { ...session };
 22	  localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
 23	}
 24	
 25	export function readSession(): Session | null {
 26	  if (memorySession) return { ...memorySession };
 27	  const raw = localStorage.getItem(SESSION_STORAGE_KEY);
 28	  if (!raw) return null;
 29	  try {
 30	    const parsed: unknown = JSON.parse(raw);
 31	    if (!isSession(parsed)) {
 32	      clearSession();
 33	      return null;
 34	    }
 35	    memorySession = parsed;
 36	    return { ...parsed };
 37	  } catch {
 38	    clearSession();
 39	    return null;
 40	  }
 41	}
