    36	export class AuthService {
    37	  constructor(
    38	    private readonly store: Store,
    39	    private readonly walletService: WalletService,
    40	  ) {}
    41	
    42	  async register(email: string, password: string): Promise<PublicAccount> {
    43	    const normalizedEmail = normalizeEmail(email);
    44	    const passwordHash = await hashPassword(password);
    45	    const account: AccountRow = {
    46	      account_id: randomUUID(),
    47	      email: normalizedEmail,
    48	      password_hash: passwordHash,
    49	      status: "ACTIVE",
    50	      created_at: new Date().toISOString(),
    51	    };
    52	    try {
    53	      this.store.transaction(() => {
    54	        this.store.db.prepare(
    55	          `INSERT INTO accounts (account_id, email, password_hash, status, created_at)
    56	           VALUES (?, ?, ?, ?, ?)`,
    57	        ).run(
    58	          account.account_id,
    59	          account.email,
    60	          account.password_hash,
    61	          account.status,
    62	          account.created_at,
    63	        );
    64	        this.walletService.assignInsideTransaction(account.account_id);
    65	      });
    66	    } catch (error) {
    67	      if (error instanceof Error && /UNIQUE constraint failed: accounts\.email/.test(error.message)) {
    68	        throw new ApiError("EMAIL_ALREADY_EXISTS", { email: normalizedEmail });
    69	      }
    70	      throw error;
    71	    }
    72	    return publicAccount(account);
    73	  }
    74	
    75	  async login(email: string, password: string): Promise<LoginResult> {
    76	    const normalizedEmail = normalizeEmail(email);
    77	    const account = this.store.findAccountByEmail(normalizedEmail);
    78	    let valid = false;
    79	    if (account) {
    80	      valid = await verifyPassword(password, account.password_hash);
    81	    } else {
    82	      await verifyAgainstDummy(password);
    83	    }
    84	
    85	    if (!account || !valid) {
    86	      throw new ApiError("INVALID_CREDENTIALS");
    87	    }
    88	
    89	    const token = randomBytes(32).toString("base64url");
    90	    const now = new Date();
    91	    const expiresAt = new Date(now.getTime() + this.store.config.sessionTtlSeconds * 1000).toISOString();
    92	    this.store.db.prepare(
    93	      "INSERT INTO sessions (token_hash, account_id, expires_at, created_at) VALUES (?, ?, ?, ?)",
    94	    ).run(tokenHash(token), account.account_id, expiresAt, now.toISOString());
    95	    return { token, expiresAt };
    96	  }
    97	
    98	  authenticate(token: string): AccountRow | undefined {
    99	    const session = this.store.db.prepare(
   100	      `SELECT a.account_id, a.email, a.password_hash, a.status, a.created_at, s.expires_at
   101	       FROM sessions s JOIN accounts a ON a.account_id = s.account_id
   102	       WHERE s.token_hash = ?`,
   103	    ).get(tokenHash(token)) as (AccountRow & { expires_at: string }) | undefined;
   104	    if (!session || Date.parse(session.expires_at) <= Date.now()) return undefined;
   105	    return session;
   106	  }
