   116	      `INSERT INTO auth_audit (timestamp, email, result, reason, origin)
   117	       VALUES (?, ?, ?, ?, ?)`,
   118	    ).run(new Date().toISOString(), normalizedEmail, result, reason ?? null, origin ?? null);
   119	  }
   120	}
