 12	function validationMessages(details: unknown): { fields: FieldErrors; general?: string } {
 13	  if (details === null || typeof details !== "object" || Array.isArray(details)) {
 14	    return { fields: {}, general: "Revisá los datos ingresados" };
 15	  }
 16	  const issues = (details as Record<string, unknown>).issues;
 17	  if (!Array.isArray(issues)) return { fields: {}, general: "Revisá los datos ingresados" };
 18	
 19	  const fields: FieldErrors = {};
 20	  for (const issue of issues) {
 21	    if (issue === null || typeof issue !== "object" || Array.isArray(issue)) continue;
 22	    const item = issue as Record<string, unknown>;
 23	    const field = item.field;
 24	    const message = item.message;
 25	    if ((field === "email" || field === "password") && typeof message === "string") {
 26	      fields[field] = message.slice(0, 200);
 27	    }
 28	  }
 29	  return Object.keys(fields).length > 0
 30	    ? { fields }
 31	    : { fields, general: "Revisá los datos ingresados" };
 32	}
