 1	export interface Session {
 2	  token: string;
 3	  expiresAt: string;
 4	}
 5	
 6	export const SESSION_STORAGE_KEY = "axis.session.v1";
 7	const EXPIRATION_NOTICE_KEY = "axis.session-expired";
 8	export const SESSION_EXPIRED_EVENT = "axis:session-expired";
 9	
10	let memorySession: Session | null = null;
11	
12	function isSession(value: unknown): value is Session {
13	  if (value === null || typeof value !== "object" || Array.isArray(value)) return false;
14	  const candidate = value as Record<string, unknown>;
15	  return typeof candidate.token === "string" && candidate.token.length > 0
16	    && typeof candidate.expiresAt === "string"
17	    && Number.isFinite(Date.parse(candidate.expiresAt));
18	}
19	
20	export function persistSession(session: Session): void {
21	  memorySession = { ...session };
22	  localStorage.setItem(SESSION_STORAGE_KEY, JSON.stringify(session));
23	}
24	
25	export function readSession(): Session | null {
26	  if (memorySession) return { ...memorySession };
27	  const raw = localStorage.getItem(SESSION_STORAGE_KEY);
28	  if (!raw) return null;
29	  try {
30	    const parsed: unknown = JSON.parse(raw);
31	    if (!isSession(parsed)) {
32	      clearSession();
33	      return null;
34	    }
35	    memorySession = parsed;
36	    return { ...parsed };
37	  } catch {
38	    clearSession();
39	    return null;
40	  }
41	}
42	
43	export function clearSession(): void {
44	  memorySession = null;
45	  localStorage.removeItem(SESSION_STORAGE_KEY);
46	}
47	
48	export function sessionIsExpired(session: Session, now = Date.now()): boolean {
49	  return now >= Date.parse(session.expiresAt);
50	}
51	
52	export function navigate(path: "/login" | "/trading", replace = false): void {
53	  const method = replace ? "replaceState" : "pushState";
54	  window.history[method]({}, "", path);
55	  window.dispatchEvent(new PopStateEvent("popstate"));
56	}
57	
58	export function expireSession(): void {
59	  clearSession();
60	  sessionStorage.setItem(EXPIRATION_NOTICE_KEY, "1");
61	  navigate("/login", true);
62	  window.dispatchEvent(new Event(SESSION_EXPIRED_EVENT));
63	}
64	
65	export function consumeExpirationNotice(): boolean {
66	  const present = sessionStorage.getItem(EXPIRATION_NOTICE_KEY) === "1";
67	  sessionStorage.removeItem(EXPIRATION_NOTICE_KEY);
68	  return present;
69	}
