  3	interface ErrorEnvelope {
  4	  error?: {
  5	    code?: unknown;
  6	    details?: unknown;
  7	  };
  8	}
  9	
 10	export interface LoginResponse extends Session {}
 11	
 12	export interface ProfileResponse {
 13	  accountId: string;
 14	  email: string;
 15	  status: "ACTIVE";
 16	  createdAt: string;
 17	}
 18	
 19	export class ApiResponseError extends Error {
 20	  constructor(
 21	    readonly code: string,
 22	    readonly status: number,
 23	    readonly details?: unknown,
 24	  ) {
 25	    super(code);
 26	    this.name = "ApiResponseError";
 27	  }
 28	}
 29	
 30	export class NetworkError extends Error {
 31	  constructor() {
 32	    super("NETWORK_ERROR");
 33	    this.name = "NetworkError";
 34	  }
 35	}
 36	
 37	const configuredBaseUrl = import.meta.env.VITE_API_BASE_URL?.trim();
 38	export const API_BASE_URL = (configuredBaseUrl || "http://127.0.0.1:3000/api/v1").replace(/\/+$/, "");
 39	
 40	function isRecord(value: unknown): value is Record<string, unknown> {
 41	  return value !== null && typeof value === "object" && !Array.isArray(value);
 42	}
 43	
 44	async function requestJson<T>(path: string, init: RequestInit): Promise<T> {
 45	  let response: Response;
 46	  try {
 47	    response = await fetch(`${API_BASE_URL}${path}`, init);
 48	  } catch {
 49	    throw new NetworkError();
 50	  }
 51	
 52	  let body: unknown;
 53	  try {
 54	    body = await response.json();
 55	  } catch {
 56	    throw new NetworkError();
 57	  }
 58	
 59	  if (!response.ok) {
 60	    const envelope = body as ErrorEnvelope;
 61	    const code = envelope.error?.code;
 62	    if (typeof code === "string") {
 63	      throw new ApiResponseError(code, response.status, envelope.error?.details);
 64	    }
 65	    throw new NetworkError();
 66	  }
 67	  return body as T;
 68	}
 69	
 70	export async function login(email: string, password: string): Promise<LoginResponse> {
 71	  const result = await requestJson<unknown>("/auth/login", {
 72	    method: "POST",
 73	    headers: { "Content-Type": "application/json" },
 74	    body: JSON.stringify({ email, password }),
 75	  });
 76	  if (!isRecord(result) || typeof result.token !== "string" || result.token.length === 0
 77	    || typeof result.expiresAt !== "string" || !Number.isFinite(Date.parse(result.expiresAt))) {
 78	    throw new NetworkError();
 79	  }
 80	  return { token: result.token, expiresAt: result.expiresAt };
 81	}
 82	
 83	export async function validateSession(session: Session): Promise<ProfileResponse> {
 84	  return requestJson<ProfileResponse>("/me", {
 85	    method: "GET",
 86	    headers: { Authorization: `Bearer ${session.token}` },
 87	  });
 88	}
 89	
 90	export async function authenticatedRequest<T>(
 91	  path: string,
 92	  session: Session,
 93	  init: RequestInit = {},
 94	): Promise<T> {
 95	  try {
 96	    return await requestJson<T>(path, {
 97	      ...init,
 98	      headers: { ...init.headers, Authorization: `Bearer ${session.token}` },
 99	    });
100	  } catch (error) {
101	    if (error instanceof ApiResponseError && error.code === "UNAUTHENTICATED") {
102	      expireSession();
103	    }
104	    throw error;
105	  }
106	}

