  webOrigins?: string[];
}

export interface RateLimitConfig {
  max: number;
  windowSeconds: number;
}

function positiveInt(name: string, raw: string | undefined, fallback?: number): number {
  if (raw === undefined && fallback !== undefined) return fallback;
  if (raw === undefined || !/^[1-9][0-9]*$/.test(raw)) {
    throw new Error(`INTERNAL_ERROR: ${name} debe ser un entero positivo`);
  }
  const value = Number(raw);
  if (!Number.isSafeInteger(value)) {
    throw new Error(`INTERNAL_ERROR: ${name} está fuera de rango`);
  }
  return value;
}

function encryptionKey(raw: string | undefined): Buffer {
  if (!raw) throw new Error("INTERNAL_ERROR: falta WALLET_ENCRYPTION_KEY");
  const value = raw.startsWith("base64:")
    ? Buffer.from(raw.slice(7), "base64")
    : Buffer.from(raw, "hex");
  if (value.length !== 32) {
    throw new Error("INTERNAL_ERROR: WALLET_ENCRYPTION_KEY debe contener exactamente 32 bytes");
  }
  return value;
}

function optionalRateLimit(
  env: NodeJS.ProcessEnv,
  maxName: string,
  windowName: string,
): RateLimitConfig | undefined {
  const max = env[maxName];
  const window = env[windowName];
  if (max === undefined && window === undefined) return undefined;
  if (max === undefined || window === undefined) {
    throw new Error(`INTERNAL_ERROR: ${maxName} y ${windowName} deben configurarse juntos`);
  }
  return { max: positiveInt(maxName, max), windowSeconds: positiveInt(windowName, window) };
}

export function loadConfig(env: NodeJS.ProcessEnv = process.env): AppConfig {
  const ttl = positiveInt("SESSION_TTL_SECONDS", env.SESSION_TTL_SECONDS, 3600);
  if (ttl < 60 || ttl > 86_400) {
    throw new Error("INTERNAL_ERROR: SESSION_TTL_SECONDS debe estar entre 60 y 86400");
  }

  if (!env.USDC_MOCK_ADDRESS) {
    throw new Error("INTERNAL_ERROR: falta USDC_MOCK_ADDRESS");
  }
  let usdcMockAddress: string;
  try {
    usdcMockAddress = getAddress(env.USDC_MOCK_ADDRESS);
  } catch {
    throw new Error("INTERNAL_ERROR: USDC_MOCK_ADDRESS no es una dirección Ethereum válida");
  }

  const sepoliaRpcUrl = env.SEPOLIA_RPC_URL;
  if (!sepoliaRpcUrl) throw new Error("INTERNAL_ERROR: falta SEPOLIA_RPC_URL");
  try {
    const url = new URL(sepoliaRpcUrl);
    if (url.protocol !== "http:" && url.protocol !== "https:") throw new Error();
  } catch {
    throw new Error("INTERNAL_ERROR: SEPOLIA_RPC_URL debe ser una URL HTTP(S) válida");
  }

  const port = positiveInt("PORT", env.PORT, 3000);
  if (port > 65_535) throw new Error("INTERNAL_ERROR: PORT está fuera de rango");

  const config: AppConfig = {
    host: env.HOST ?? "127.0.0.1",
    port,
    databasePath: env.DATABASE_PATH ?? "./data/exchange.sqlite",
    sessionTtlSeconds: ttl,
    walletEncryptionKey: encryptionKey(env.WALLET_ENCRYPTION_KEY),
    usdcMockAddress,
    sepoliaRpcUrl,
    hdMnemonicPassphrase: env.HD_MNEMONIC_PASSPHRASE ?? "",
  };
  if (env.HD_MNEMONIC !== undefined) config.hdMnemonic = env.HD_MNEMONIC;
  const registerRateLimit = optionalRateLimit(
    env,
    "REGISTER_RATE_LIMIT_MAX",
    "REGISTER_RATE_LIMIT_WINDOW_SECONDS",
  );
  if (registerRateLimit) config.registerRateLimit = registerRateLimit;
  const loginRateLimit = optionalRateLimit(
    env,
    "LOGIN_RATE_LIMIT_MAX",
    "LOGIN_RATE_LIMIT_WINDOW_SECONDS",
  );
  if (loginRateLimit) config.loginRateLimit = loginRateLimit;
  if (env.WEB_ORIGINS !== undefined) {
    const webOrigins = env.WEB_ORIGINS.split(",").map((origin) => origin.trim()).filter(Boolean);
    if (webOrigins.length === 0) {
      throw new Error("INTERNAL_ERROR: WEB_ORIGINS debe contener al menos un origen");
    }
    for (const origin of webOrigins) {
      try {
        const url = new URL(origin);
        if ((url.protocol !== "http:" && url.protocol !== "https:") || url.origin !== origin) {
          throw new Error();
        }
      } catch {
        throw new Error(`INTERNAL_ERROR: WEB_ORIGINS contiene un origen inválido: ${origin}`);
      }
    }
    config.webOrigins = webOrigins;
  }
  return config;
}

